"use client"

import { useMemo, useState } from "react"
import {
  flexRender,
  getCoreRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  useReactTable,
  type ColumnDef,
  type SortingState,
} from "@tanstack/react-table"

import { CanonicalTableBoundary } from "@/components/DataTableComponents/CanonicalTableBoundary"
import { CanonicalTableDensityControl } from "@/components/DataTableComponents/CanonicalTableDensityControl"
import { DataTableSearch } from "@/components/DataTableComponents/DataTableSearch"
import { DataTablePagination } from "@/components/DataTableComponents/DataTablePagination"
import { useCanonicalTablePreferences } from "@/components/DataTableComponents/useCanonicalTablePreferences"
import {
  createCanonicalTableQuery,
  type CanonicalTableContract,
} from "@/components/DataTableComponents/table-system-contract"

export type FinancialStatementLineTableRow = {
  accountId: string
  code: string
  nameEn: string
  nameFr: string | null
  classificationSource: string
  amount: string
}

function formatMoney(value: string, locale: "en" | "fr", currency: string) {
  const amount = Number(value)
  return new Intl.NumberFormat(locale === "fr" ? "fr-FR" : "en-US", {
    style: "currency",
    currency,
    minimumFractionDigits: 0,
    maximumFractionDigits: 2,
  }).format(Number.isFinite(amount) ? amount : 0)
}

function SortHeader({
  label,
  sortLabel,
  column,
}: {
  label: string
  sortLabel: string
  column: { getIsSorted: () => false | "asc" | "desc"; toggleSorting: (desc?: boolean) => void }
}) {
  const sorted = column.getIsSorted()
  return (
    <button
      type="button"
      aria-label={sortLabel}
      aria-pressed={Boolean(sorted)}
      onClick={() => column.toggleSorting(sorted === "asc")}
      className="font-semibold hover:text-[var(--dash-text)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--dash-focus)]"
    >
      {label}{sorted ? (sorted === "asc" ? " ↑" : " ↓") : null}
    </button>
  )
}

export function FinancialStatementLinesTable({
  title,
  lines,
  currency,
  contract,
  periodId,
  locale: localeProp = "en",
}: {
  title: string
  lines: FinancialStatementLineTableRow[]
  currency: string
  contract: CanonicalTableContract
  periodId?: string
  locale?: "en" | "fr"
}) {
  const locale: "en" | "fr" = localeProp
  const copy = locale === "fr"
    ? { account: "Compte", classification: "Classification", amount: "Montant", evidence: "Preuve", posted: "Grand livre poste", sort: "Trier par", page: "Page", previous: "Precedent", next: "Suivant" }
    : { account: "Account", classification: "Classification", amount: "Amount", evidence: "Evidence", posted: "Posted ledger", sort: "Sort by", page: "Page", previous: "Previous", next: "Next" }
  const [sorting, setSorting] = useState<SortingState>([{ id: "code", desc: false }])
  const [search, setSearch] = useState("")
  const filteredLines = useMemo(() => {
    const query = search.trim().toLocaleLowerCase()
    return lines.filter((line) => [line.code, line.nameEn, line.nameFr, line.classificationSource, line.amount].join(" ").toLocaleLowerCase().includes(query))
  }, [lines, search])
  const {
    columnVisibility,
    columnOrder,
    density,
    setColumnVisibility,
    setColumnOrder,
    setDensity,
  } = useCanonicalTablePreferences(contract)

  const columns = useMemo<ColumnDef<FinancialStatementLineTableRow>[]>(
    () => [
      {
        accessorKey: "code",
        enableHiding: false,
        header: ({ column }) => <SortHeader label={locale === "fr" ? "Compte" : "Account code"} sortLabel={`${copy.sort} ${locale === "fr" ? "Compte" : "Account code"}`} column={column} />,
        cell: ({ row }) => <span className="font-mono text-xs font-semibold text-[var(--dash-brand-strong)]">{row.original.code}</span>,
      },
      {
        id: "account",
        accessorFn: (row) => locale === "fr" ? row.nameFr || row.nameEn : row.nameEn,
        header: ({ column }) => <SortHeader label={copy.account} sortLabel={`${copy.sort} ${copy.account}`} column={column} />,
        cell: ({ row }) => <span className="block max-w-72 truncate text-xs font-medium text-[var(--dash-text)]">{locale === "fr" ? row.original.nameFr || row.original.nameEn : row.original.nameEn}</span>,
      },
      { accessorKey: "classificationSource", header: copy.classification, cell: ({ row }) => <span className="text-xs text-[var(--dash-text-soft)]">{row.original.classificationSource}</span> },
      {
        accessorKey: "amount",
        header: ({ column }) => <SortHeader label={copy.amount} sortLabel={`${copy.sort} ${copy.amount}`} column={column} />,
        cell: ({ row }) => <span className="block whitespace-nowrap text-right tabular-nums font-semibold text-[var(--dash-text)]">{formatMoney(row.original.amount, locale, currency)}</span>,
        sortingFn: (rowA, rowB) => Number(rowA.original.amount) - Number(rowB.original.amount),
      },
      { id: "evidence", header: copy.evidence, cell: () => <span className="text-xs text-[var(--dash-text-soft)]">{copy.posted}</span> },
    ],
    [copy, currency, locale],
  )

  const table = useReactTable({
    data: filteredLines,
    columns,
    getRowId: (row) => row.accountId,
    state: { sorting, columnVisibility, columnOrder },
    onSortingChange: setSorting,
    onColumnVisibilityChange: setColumnVisibility,
    onColumnOrderChange: setColumnOrder,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    initialState: { pagination: { pageIndex: 0, pageSize: 25 } },
  })
  const pageIndex = table.getState().pagination.pageIndex
  const pageSize = table.getState().pagination.pageSize
  const query = createCanonicalTableQuery(contract, {
    search,
    filters: periodId ? { periodId: [periodId] } : {},
    sort: sorting,
    pageIndex,
    pageSize,
  })
  const state = filteredLines.length ? "ready" : search.trim() ? "no-results" : "empty"

  return (
    <CanonicalTableBoundary contract={contract} locale={locale} query={query} state={state} density={density}>
      <div data-statement-title={title} data-statement-period-id={periodId} className="min-w-0 border-t border-[var(--dash-border-subtle)]">
        <div className="dashboard-table-toolbar flex flex-nowrap items-center gap-3 overflow-x-auto border-b border-[var(--dash-border-subtle)] bg-[var(--dash-surface)]/50 p-3">
          <div className="min-w-48 flex-1"><DataTableSearch value={search} onChange={(value) => { setSearch(value); table.setPageIndex(0) }} ariaLabel={`${locale === "fr" ? "Rechercher" : "Search"}: ${title}`} placeholder={locale === "fr" ? "Rechercher des comptes..." : "Search accounts..."} clearButtonLabel={locale === "fr" ? "Effacer la recherche" : "Clear table search"} /></div>
          <div className="shrink-0"><CanonicalTableDensityControl density={density} locale={locale} onDensityChange={setDensity} /></div>
        </div>
        <div className="max-h-[28rem] overflow-auto" role="region" tabIndex={0} aria-label={title}>
        <table className="dashboard-table-base w-full min-w-[760px] text-sm">
          <caption className="sr-only">{title} account detail</caption>
          <thead className="sticky top-0 z-10 bg-[var(--dash-surface)] text-left text-[0.68rem] uppercase tracking-[0.12em] text-[var(--dash-text-faint)]">
            {table.getHeaderGroups().map((headerGroup) => <tr key={headerGroup.id}>{headerGroup.headers.map((header) => <th key={header.id} scope="col" data-column-id={header.column.id} data-frozen={header.column.id === "code" || header.column.id === "account" ? "start" : undefined} className={`whitespace-nowrap px-4 py-2.5 font-semibold ${header.column.id === "code" ? "sticky left-0 z-20 min-w-36 bg-[var(--dash-surface)]" : ""} ${header.column.id === "account" ? "sticky left-36 z-20 min-w-56 bg-[var(--dash-surface)]" : ""} ${header.column.id === "amount" ? "text-right" : ""}`}>{header.isPlaceholder ? null : flexRender(header.column.columnDef.header, header.getContext())}</th>)}</tr>)}
          </thead>
          <tbody>
            {table.getRowModel().rows.length ? table.getRowModel().rows.map((row) => <tr key={row.id} className="border-b border-[var(--dash-border-subtle)] hover:bg-[var(--dash-brand-soft)]/35">{row.getVisibleCells().map((cell) => <td key={cell.id} data-column-id={cell.column.id} data-frozen={cell.column.id === "code" || cell.column.id === "account" ? "start" : undefined} className={`px-4 py-2.5 ${cell.column.id === "code" ? "sticky left-0 z-10 min-w-36 bg-[var(--dash-surface)]" : ""} ${cell.column.id === "account" ? "sticky left-36 z-10 min-w-56 bg-[var(--dash-surface)]" : ""}`}>{flexRender(cell.column.columnDef.cell, cell.getContext())}</td>)}</tr>) : <tr><td colSpan={5} className="px-4 py-10 text-center text-sm text-[var(--dash-text-soft)]">{search.trim() ? (locale === "fr" ? "Aucun résultat." : "No results.") : locale === "fr" ? "Aucune activite postee dans cette section pour la periode selectionnee." : "No posted activity in this section for the selected period."}</td></tr>}
          </tbody>
        </table>
        </div>
        <nav aria-label={`${title} pagination`} className="border-t border-[var(--dash-border-subtle)] p-3">
          <DataTablePagination table={table} variant="landing" locale={locale} showSelectionCount={false} pageSizeOptions={contract.query.allowedPageSizes} />
        </nav>
      </div>
    </CanonicalTableBoundary>
  )
}

"use client"
import { useEffect, useRef, useState } from "react"
import { getAccountantInvitationDeliveryAction } from "@/actions/accounting/firm-engagement.actions"
import { firmEngagementCopy } from "./firm-engagement-copy"

type Result = Extract<Awaited<ReturnType<typeof getAccountantInvitationDeliveryAction>>, { success: true }>["data"]
export function AccountantInvitationDelivery({ locale = "en" }: { locale?: "en" | "fr" }) {
  const t = firmEngagementCopy[locale], sequence = useRef(0)
  const [data, setData] = useState<Result | null>(null), [busy, setBusy] = useState(false), [failed, setFailed] = useState(false)
  async function load() {
    const revision = ++sequence.current
    setData(null); setBusy(true); setFailed(false)
    try { const r = await getAccountantInvitationDeliveryAction()
      if (revision === sequence.current) { if (r.success) setData(r.data); else setFailed(true) }
    } catch { if (revision === sequence.current) setFailed(true) }
    finally { if (revision === sequence.current) setBusy(false) }
  }
  useEffect(() => {
    void load()
    const change = () => { ++sequence.current; setData(null); if (!document.hidden) void load() }
    document.addEventListener("visibilitychange", change)
    return () => { ++sequence.current; document.removeEventListener("visibilitychange", change) }
  }, [])
  const label = (v: string) => (t.statuses as Record<string, string>)[v] ?? v
  return <section id="accountant-invitation-delivery" aria-labelledby="invitation-delivery-title" aria-busy={busy} className="dashboard-glass-panel min-w-0 space-y-4 rounded-lg p-5">
    <h2 id="invitation-delivery-title" className="text-xl font-semibold">{t.deliveryTitle}</h2><p>{t.deliveryHelp}</p>
    <button className="dashboard-button-secondary min-h-11 rounded-lg px-3 focus-visible:outline focus-visible:outline-2" disabled={busy} onClick={() => void load()}>{t.refresh}</button>
    {busy && <p role="status">{t.loading}</p>}{failed && <p role="alert">{t.unavailable}</p>}
    {data?.partial && <p role="status">{t.partial}</p>}
    {data && !data.rows.length && <p>{t.deliveryEmpty}</p>}
    <ul className="space-y-3">{data?.rows.map(row => <li key={row.id} className="rounded-lg border border-[var(--dash-border)] p-3">
      <p className="break-all">{row.email} · {t.roles[row.scope]}</p>
      <p>{t.acceptance}: {label(row.acceptance)} · {t.delivery}: {label(row.delivery)}</p>
      <p>{t.attempts}: {row.attempts ?? "—"} / {row.maxAttempts ?? "—"}</p>
      {row.retryAt && <p>{t.retryAt}: {new Date(row.retryAt).toLocaleString(locale)}</p>}
      <p>{t.expiry}: {new Date(row.expiresAt).toLocaleString(locale)}</p>
    </li>)}</ul>
  </section>
}

"use client"

import { useCallback, useEffect, useRef, useState } from "react"
import { flushSync } from "react-dom"
import Link from "next/link"
import { getAccountantPortfolioAction } from "@/actions/accounting/accountant-access.actions"
import { RouteStatePanel } from "@/components/dashboard/primitives/command-center-primitives"
import type { AccountantPortfolio as Portfolio } from "@/services/accounting/accountant-access.service"
import { AccountantPortfolio, portfolioButton } from "./AccountantPortfolio"
import { AccountantWorkDesk } from "./AccountantWorkDesk"
import type { DelegatedEvidenceRecovery } from "./DelegatedEvidenceDesk"
import { accountantPortfolioCopy } from "./accountant-portfolio-copy"
import { dashboardLoginRecoveryHref } from "@/lib/security/dashboard-session-recovery"

type PageInput = { search?: string; cursor?: string; pageSize?: number }
type Failure = keyof typeof accountantPortfolioCopy.en.errors

export function AccountantPortfolioWorkspace({ locale = "en", initialInput = {} }: { locale?: string; initialInput?: PageInput }) {
  const language = locale === "fr" ? "fr" : "en"
  const copy = accountantPortfolioCopy[language]
  const [search, setSearch] = useState(initialInput.search ?? "")
  const [data, setData] = useState<Portfolio | null>(null)
  const [pending, setPending] = useState(true)
  const [failure, setFailure] = useState<Failure | null>(null)
  const input = useRef<PageInput>(initialInput)
  const revision = useRef(0)
  // Keep only the exact uncertain command across private-DOM removal. Never persist it.
  const evidenceRecovery = useRef<DelegatedEvidenceRecovery | null>(null)
  const heading = useRef<HTMLHeadingElement>(null)
  const route = `/${language}/dashboard/accounting/accountant-portfolio`
  const initialKey = JSON.stringify(initialInput)

  const load = useCallback(async (next: PageInput, focus = false) => {
    const current = ++revision.current
    input.current = next
    // Clear both portfolio and work-desk private state before any reauthorization.
    setData(null); setPending(true); setFailure(null)
    try {
      const response = await getAccountantPortfolioAction(next)
      if (current !== revision.current) return
      if (response.success) {
        if (evidenceRecovery.current?.actorId !== response.data.accountantUserId) evidenceRecovery.current = null
        setData(response.data)
        input.current = { ...next, search: response.data.page.search, pageSize: response.data.page.pageSize }
        const query = new URLSearchParams({ search: response.data.page.search, pageSize: String(response.data.page.pageSize) })
        if (next.cursor) query.set("cursor", next.cursor)
        window.history.replaceState(window.history.state, "", `${route}?${query}`)
      } else {
        if (response.code === "FORBIDDEN" || response.code === "AUTH_REQUIRED" || response.code === "FRESH_AUTH_REQUIRED") evidenceRecovery.current = null
        setFailure(response.code === "AUTH_REQUIRED" || response.code === "FRESH_AUTH_REQUIRED" ? "stale_session"
          : response.code === "FORBIDDEN" ? "permission_denied"
            : response.code === "BUSINESS_RULE_VIOLATION" || response.code === "VALIDATION_ERROR" ? "stale_data" : "error")
      }
    } catch { if (current === revision.current) setFailure("error") }
    finally {
      if (current === revision.current) { setPending(false); if (focus) heading.current?.focus() }
    }
  }, [route])

  useEffect(() => {
    input.current = JSON.parse(initialKey) as PageInput
    setSearch(input.current.search ?? "")
    void load(input.current)
    const hide = () => {
      revision.current++
      // Flush before the browser can freeze a private DOM snapshot in BFCache.
      flushSync(() => { setData(null); setPending(true); setFailure(null) })
    }
    const visible = () => { if (document.visibilityState === "hidden") hide(); else void load(input.current) }
    const restore = (event: PageTransitionEvent) => { if (event.persisted) void load(input.current) }
    document.addEventListener("visibilitychange", visible)
    window.addEventListener("pagehide", hide)
    window.addEventListener("pageshow", restore)
    return () => {
      revision.current++
      document.removeEventListener("visibilitychange", visible)
      window.removeEventListener("pagehide", hide)
      window.removeEventListener("pageshow", restore)
    }
  }, [load, initialKey])

  useEffect(() => {
    if (!data?.clients.length) return
    const expires = Math.min(...data.clients.map(row => Date.parse(row.grant.expiresAt)))
    // Known expiry removes details and asks the server for a new authorized page.
    if (!Number.isFinite(expires)) return
    const delay = expires - Date.now()
    if (delay > 2_147_483_647) return
    const timer = window.setTimeout(() => void load(input.current), Math.max(0, delay))
    return () => window.clearTimeout(timer)
  }, [data, load])

  const returnQuery = new URLSearchParams({ search: search.trim(), pageSize: String(input.current.pageSize ?? 10) })
  return <div id="accountant-portfolio-workspace" className="min-w-0 space-y-5">
    <form className="dashboard-glass-panel rounded-lg p-4" onSubmit={event => {
      event.preventDefault(); void load({ search: search.trim(), pageSize: input.current.pageSize }, true)
    }}>
      <label htmlFor="portfolio-search" className="block text-sm font-medium">{copy.search}</label>
      <p id="portfolio-search-help" className="mb-2 text-sm text-[var(--dash-text-soft)]">{copy.searchHelp}</p>
      <div className="flex flex-wrap gap-3">
        <input id="portfolio-search" name="search" type="search" maxLength={100} value={search} onChange={e => setSearch(e.target.value)} aria-describedby="portfolio-search-help" className="min-h-11 w-full min-w-0 basis-full rounded-lg border border-[var(--dash-border-subtle)] bg-[var(--dash-surface)] px-3 text-[var(--dash-text)] focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--dash-brand)] sm:w-auto sm:flex-1 sm:basis-auto" />
        <button className={portfolioButton} disabled={pending} type="submit">{copy.submit}</button>
        <button className={portfolioButton} disabled={pending} type="button" onClick={() => void load(input.current, true)}>{copy.refresh}</button>
      </div>
    </form>
    <section aria-labelledby="portfolio-heading" aria-busy={pending}>
      <h2 ref={heading} id="portfolio-heading" tabIndex={-1} className="mb-3 text-lg font-semibold focus-visible:outline focus-visible:outline-2 focus-visible:outline-[var(--dash-brand)]">{copy.title}</h2>
      <div role="status" aria-live="polite" className={pending || failure ? "mb-3 text-sm" : "sr-only"}>{pending ? copy.loading : failure ? copy.errors[failure][0] : data ? `${data.page.loadedCount} ${copy.scope}` : ""}</div>
      {pending && <RouteStatePanel kind="loading" title={copy.loading} message={copy.searchHelp} />}
      {failure && <>
        <RouteStatePanel kind={failure} title={copy.errors[failure][0]} message={copy.errors[failure][1]} action={{ label: failure === "stale_data" ? copy.restart : copy.retry, onClick: () => void load(failure === "stale_data" ? { search: search.trim(), pageSize: 10 } : input.current, true) }} />
        {failure === "stale_session" && <Link prefetch={false} className={`${portfolioButton} mt-3`} href={dashboardLoginRecoveryHref(`${route}?${returnQuery}`, language)}>{copy.signIn}</Link>}
      </>}
      {data && <AccountantPortfolio portfolio={data} locale={language} onPage={cursor => void load({ ...input.current, cursor }, true)} />}
    </section>
    {data && <div><p className="mb-3 text-sm text-[var(--dash-text-soft)]">{copy.workScope}</p><AccountantWorkDesk locale={language} evidenceRecoveryRef={evidenceRecovery} /></div>}
  </div>
}

