        <p>{t[row.payload.kind]} — {row.payload.kind === "FEE" ? `${row.payload.currency} ${row.payload.amount}` : `${person(row.subjectUserId)}: ${row.payload.minutes} ${t.minutes.toLowerCase()}`} — #{row.version}</p>
        <p>{row.reviewedById ? t.reviewed : t.unreviewed}</p>
        {(row.payload.kind !== "EFFORT" || row.recordedById === desk.actorId) && <Button disabled={busy || !!pending || (row.payload.kind !== "EFFORT" && mode !== "manager")} variant="outline" onClick={() => edit(row)}>{t.correct}</Button>}
        {mode === "manager" && !row.reviewedById && row.actorId !== desk.actorId && row.recordedById !== desk.actorId && <Button disabled={busy || !!pending || reason.trim().length < 10} variant="outline" onClick={() => void submit({ ...scope, engagementId, command: "REVIEW", recordKey: row.recordKey, expectedVersion: row.version, idempotencyKey: crypto.randomUUID(), reason })}>{t.review}</Button>}
        <details><summary className="min-h-11 cursor-pointer py-2">{t.versions}</summary>{cohort.history.filter(item => item.recordKey === row.recordKey).map(item => <p className="break-words" key={item.id}>#{item.version} — {item.createdAt} — {item.actorId} — {item.reason}</p>)}</details>
      </article>)}
    </>}
  </section>
}

"use client"

import { createContext, useCallback, useContext, useEffect, useId, useRef, useState, type FormEvent, type ReactNode } from "react"
import { useRouter } from "next/navigation"
import { postJournalEntryAction, reverseJournalEntryAction } from "@/actions/accounting/journals.actions"
import { stepUpWithPasswordAction } from "@/actions/security/step-up-auth.actions"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Textarea } from "@/components/ui/textarea"
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog"
import { getJournalWorkflowCopy } from "./journal-workflow-copy"

type Props = { locale: string; entryId: string; entryNumber: string; operation: "post" | "reverse" }
type Recovery = "none" | "identity" | "session" | "refresh"
const commandKey = ({ entryId, operation }: Props) => `${entryId}:${operation}`
const WorkflowFeedback = createContext<{
  openReview: (command: Props) => void
  registerTrigger: (key: string, element: HTMLButtonElement | null) => void
  activeKey: string | null
  completed: ReadonlySet<string>
} | null>(null)

// Table cells can remount when fresh RSC columns arrive. Own the command and
// dialog outside those cells, including while authentication or a write waits.
export function JournalWorkflowFeedback({ children, readRevision }: { children: ReactNode; readRevision?: string | null }) {
  const [message, setMessage] = useState<string | null>(null)
  const [commands, setCommands] = useState<ReadonlyMap<string, Props>>(() => new Map())
  const [activeKey, setActiveKey] = useState<string | null>(null)
  const [completed, setCompleted] = useState<ReadonlySet<string>>(() => new Set())
  const status = useRef<HTMLParagraphElement>(null)
  const region = useRef<HTMLDivElement>(null)
  const triggers = useRef(new Map<string, HTMLButtonElement>())
  const registerTrigger = useCallback((key: string, element: HTMLButtonElement | null) => {
    if (element) triggers.current.set(key, element)
    else triggers.current.delete(key)
  }, [])
  const openReview = useCallback((selected: Props) => {
    const key = commandKey(selected)
    setCommands(current => new Map(current).set(key, selected))
    setActiveKey(key)
  }, [])
  useEffect(() => { if (message) status.current?.focus() }, [message])
  return <WorkflowFeedback.Provider value={{ openReview, registerTrigger, completed, activeKey }}>
    <div ref={region} tabIndex={-1} data-journal-workflow-region className="min-w-0 focus-visible:outline focus-visible:outline-2 focus-visible:outline-[var(--dash-brand)]">
      {message && <p ref={status} role="status" aria-live="polite" tabIndex={-1} data-journal-workflow-feedback
        className="dashboard-landing-theme dark rounded-lg border border-[var(--dash-success)] bg-[var(--dash-success-soft)] p-3 text-sm text-[var(--dash-text)] focus-visible:outline focus-visible:outline-2 focus-visible:outline-[var(--dash-brand)]">{message}</p>}
      {children}
    </div>
    {[...commands].map(([key, command]) => <JournalEntryReview key={key} {...command} readRevision={readRevision} open={activeKey === key} onOpenChange={next => setActiveKey(next ? key : null)}
      onSuccess={receipt => { setMessage(receipt); setCompleted(current => new Set([...current, commandKey(command)])) }}
      focusSuccess={() => status.current?.focus()}
      returnFocus={() => {
        const currentTrigger = triggers.current.get(commandKey(command))
        if (currentTrigger?.isConnected && !currentTrigger.disabled) currentTrigger.focus()
        else region.current?.focus()
      }} />)}
  </WorkflowFeedback.Provider>
}

export function JournalEntryActions(props: Props) {
  const workflow = useContext(WorkflowFeedback)
  // The journals page supplies the stable provider; keep isolated consumers usable.
  return workflow ? <JournalEntryTrigger {...props} /> : <JournalWorkflowFeedback><JournalEntryTrigger {...props} /></JournalWorkflowFeedback>
}

function JournalEntryTrigger(props: Props) {
  const workflow = useContext(WorkflowFeedback)!
  const [ready, setReady] = useState(false)
  useEffect(() => { setReady(true) }, [])
  const key = commandKey(props)
  const copy = getJournalWorkflowCopy(props.locale).actions
  const label = props.operation === "reverse" ? copy.reverse : copy.post
  const register = useCallback((element: HTMLButtonElement | null) => workflow.registerTrigger(key, element), [workflow.registerTrigger, key])
  return <div className="min-w-0" data-journal-entry-action={props.entryId}>
    <Button ref={register} type="button" variant="outline" size="sm" disabled={!ready || workflow.completed.has(key)} aria-busy={!ready}
      className="dashboard-button-secondary min-h-9 whitespace-normal" aria-label={`${label} — ${props.entryNumber}`}
      aria-haspopup="dialog" aria-expanded={workflow.activeKey === key} onClick={() => workflow.openReview(props)}>{label}</Button>
  </div>
}

function JournalEntryReview({ locale, entryId, entryNumber, operation, readRevision, open, onOpenChange, onSuccess, returnFocus, focusSuccess }: Props & {
  readRevision?: string | null; open: boolean; onOpenChange: (open: boolean) => void; onSuccess: (receipt: string) => void; returnFocus: () => void; focusSuccess: () => void
}) {
  const copy = getJournalWorkflowCopy(locale).actions
  const router = useRouter()
  const id = useId()
  const heading = useRef<HTMLHeadingElement>(null)
  const confirm = useRef<HTMLButtonElement>(null)
  const passwordInput = useRef<HTMLInputElement>(null)
  const feedback = useRef<HTMLDivElement>(null)
  const inFlight = useRef(false)
  const pendingRefresh = useRef<{ revision: string | null | undefined } | null>(null)
  const returnToConfirm = useRef(false)
  const [busy, setBusy] = useState(false)
  const [reason, setReason] = useState("")
  const [date, setDate] = useState("")
  const [password, setPassword] = useState("")
  const [recovery, setRecovery] = useState<Recovery>("none")
  const [message, setMessage] = useState<string | null>(null)
  const [notice, setNotice] = useState<string | null>(null)
  const [completed, setCompleted] = useState(false)
  const reversing = operation === "reverse"
  const confirmLabel = reversing ? copy.confirmReverse : copy.confirmPost

  useEffect(() => {
    if (!open || busy) return
    if (recovery === "identity") passwordInput.current?.focus()
    else if (returnToConfirm.current) { returnToConfirm.current = false; confirm.current?.focus() }
    else if (message) feedback.current?.focus()
  }, [open, busy, recovery, message])

  useEffect(() => {
    if (pendingRefresh.current && readRevision && readRevision !== pendingRefresh.current.revision) {
      pendingRefresh.current = null
      setRecovery("none")
      setMessage(null)
    }
  }, [readRevision])

  function changeOpen(next: boolean) {
    if (inFlight.current) return
    onOpenChange(next)
    setPassword("")
    if (next && recovery === "none") { setMessage(null); setNotice(null) }
  }

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    if (inFlight.current || recovery !== "none" || completed) return
    const reversalDate = new Date(`${date}T00:00:00.000Z`)
    if (reversing && (!reason.trim() || !/^\d{4}-\d{2}-\d{2}$/.test(date) || !Number.isFinite(reversalDate.getTime()) || reversalDate.toISOString().slice(0, 10) !== date)) {
      setMessage(copy.invalid)
      return
    }
    inFlight.current = true
    setBusy(true); setMessage(null); setNotice(null)
    try {
      const result = reversing
        ? await reverseJournalEntryAction({ journalEntryId: entryId, reason: reason.trim(), reversalDate: `${date}T00:00:00.000Z` })
        : await postJournalEntryAction({ journalEntryId: entryId })
      if (result.success) {
        const receipt = `${entryNumber}: ${reversing ? copy.reversed : copy.posted}`
        setCompleted(true); onSuccess(receipt); onOpenChange(false)
        router.refresh()
      } else if (result.code === "FRESH_AUTH_REQUIRED") {
        setPassword(""); setRecovery("identity"); setMessage(copy.fresh)
      } else if (result.code === "AUTH_REQUIRED") {
        setRecovery("session"); setMessage(copy.authRequired)
      } else if (result.code === "FORBIDDEN") {
        setRecovery("refresh"); setMessage(copy.denied)
      } else if (result.code === "CONFLICT" || result.code === "CONCURRENCY_CONFLICT") {
        setRecovery("refresh"); setMessage(copy.changed)
      } else if (result.code === "SOD_VIOLATION") {
        setRecovery("refresh"); setMessage(copy.independent)
      } else if (result.code === "BUSINESS_RULE_VIOLATION" || result.code === "VALIDATION_ERROR") {
        setMessage(copy.rule)
      } else {
        setRecovery("refresh"); setMessage(copy.uncertain)
      }
    } catch {
      setRecovery("refresh"); setMessage(copy.uncertain)
    } finally { inFlight.current = false; setBusy(false) }
  }

  async function confirmIdentity(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    if (inFlight.current || !password || recovery !== "identity") return
    const enteredPassword = password
    setPassword(""); setBusy(true); setMessage(null); inFlight.current = true
    try {
      const result = await stepUpWithPasswordAction({ password: enteredPassword })
      if (result.success) {
        setRecovery("none"); setNotice(copy.verified); returnToConfirm.current = true
      } else if (result.code === "AUTH_REQUIRED") {
        setRecovery("session"); setMessage(copy.authRequired)
      } else setMessage(result.code === "RATE_LIMITED" ? copy.identityRateLimited : copy.identityFailed)
    } catch { setMessage(copy.identityFailed) }
    finally { inFlight.current = false; setBusy(false) }
  }

  return <Dialog open={open} onOpenChange={changeOpen}>
      <DialogContent className="dashboard-landing-theme dark max-h-[90dvh] w-[calc(100%_-_2rem)] max-w-lg overflow-y-auto rounded-xl border-[var(--dash-border)] bg-[var(--dash-surface)] text-[var(--dash-text)] motion-reduce:animate-none motion-reduce:transition-none [overflow-wrap:anywhere]" closeLabel={copy.close} closeDisabled={busy}
        onOpenAutoFocus={event => { event.preventDefault(); heading.current?.focus() }}
        onCloseAutoFocus={event => {
          event.preventDefault()
          if (completed) focusSuccess()
          else returnFocus()
        }}
        onEscapeKeyDown={event => { if (inFlight.current) event.preventDefault() }}
        onInteractOutside={event => { if (inFlight.current) event.preventDefault() }}>
        <DialogHeader className="pr-6 text-left">
          <DialogTitle ref={heading} tabIndex={-1} className="leading-snug focus-visible:outline focus-visible:outline-2 focus-visible:outline-[var(--dash-brand)]">{reversing ? copy.reviewReverse : copy.reviewPost} — {entryNumber}</DialogTitle>
          <DialogDescription className="text-[var(--dash-text-soft)]">{reversing ? copy.reverseDescription : copy.postDescription}</DialogDescription>
        </DialogHeader>
        <form id={`${id}-review`} aria-label={reversing ? copy.reviewReverse : copy.reviewPost} aria-busy={busy} onSubmit={submit}>
          {reversing && <fieldset disabled={busy || recovery !== "none"} className="min-w-0 space-y-4">
            <div className="space-y-2"><label htmlFor={`${id}-reason`} className="text-sm font-medium">{copy.reason}</label>
              <Textarea id={`${id}-reason`} required value={reason} onChange={event => setReason(event.target.value)} className="dashboard-control min-h-24" /></div>
            <div className="space-y-2"><label htmlFor={`${id}-date`} className="text-sm font-medium">{copy.date}</label>
              <Input id={`${id}-date`} type="date" required value={date} onChange={event => setDate(event.target.value)} aria-describedby={`${id}-date-help`} className="dashboard-control" />
              <p id={`${id}-date-help`} className="text-sm text-[var(--dash-text-soft)]">{copy.dateHelp}</p></div>
          </fieldset>}
        </form>
        {message && <div ref={feedback} role="alert" tabIndex={-1} className="rounded-lg border border-[var(--dash-warning)] bg-[var(--dash-warning-soft)] p-3 text-sm focus-visible:outline focus-visible:outline-2 focus-visible:outline-[var(--dash-brand)]">{message}</div>}
        {recovery === "identity" && <form onSubmit={confirmIdentity} aria-label={copy.identity} aria-busy={busy} className="space-y-3 rounded-lg border border-[var(--dash-border)] p-3">
          <label htmlFor={`${id}-password`} className="block text-sm font-medium">{copy.password}</label>
          <Input ref={passwordInput} id={`${id}-password`} type="password" autoComplete="current-password" required value={password} onChange={event => setPassword(event.target.value)} disabled={busy} className="dashboard-control" />
          <Button type="submit" disabled={busy || !password} className="dashboard-button-primary h-auto min-h-10 w-full whitespace-normal">{busy ? copy.verifying : copy.identity}</Button>
        </form>}
        {notice && <p role="status" aria-live="polite" className="text-sm text-[var(--dash-info)]">{notice}</p>}
        {recovery === "session" && <a className="text-sm text-[var(--dash-brand)] underline underline-offset-4" href={`/${locale === "fr" ? "fr" : "en"}/login`}>{copy.signIn}</a>}
        {recovery === "refresh" && <Button type="button" variant="outline" className="dashboard-button-secondary h-auto min-h-10 whitespace-normal" onClick={() => { pendingRefresh.current = { revision: readRevision }; changeOpen(false); router.refresh() }}>{copy.refresh}</Button>}
        <DialogFooter className="gap-2 sm:space-x-0">
          <Button type="button" variant="outline" className="dashboard-button-secondary h-auto min-h-10 whitespace-normal" disabled={busy} onClick={() => changeOpen(false)}>{copy.cancel}</Button>
          <Button ref={confirm} type="submit" form={`${id}-review`} className="dashboard-button-primary h-auto min-h-10 whitespace-normal" disabled={busy || recovery !== "none" || completed}>{busy ? copy.working : confirmLabel}</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
}

"use client"
import { useEffect, useId, useRef, useState } from "react"
import { getObligationRegisterAction, saveObligationAction, reviewObligationAction } from "@/actions/accounting/obligation-register.actions"
import { stepUpWithPasswordAction } from "@/actions/security/step-up-auth.actions"
import type { ObligationCode, ObligationCommand, ObligationItem, ObligationRegister as Register } from "@/services/compliance/obligation-register.contract"

const button = "dashboard-button-primary min-h-11 rounded-lg px-3 py-2 text-sm disabled:opacity-50 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2"
const field = "dashboard-control min-h-11 w-full rounded-lg p-2"
const names = {
  en: { CLOSE_EVIDENCE_COLLECTION: "Close evidence collection", CM_VAT_MONTHLY: "Cameroon VAT — country review required", CM_CNPS_EVIDENCE: "Cameroon CNPS — restricted payroll evidence" },
  fr: { CLOSE_EVIDENCE_COLLECTION: "Collecte des justificatifs de clôture", CM_VAT_MONTHLY: "TVA Cameroun — examen pays requis", CM_CNPS_EVIDENCE: "CNPS Cameroun — justificatifs de paie restreints" },
}
const states: Record<string, [string, string]> = {
  UNKNOWN: ["Unknown / review required", "Inconnu / examen requis"], NOT_APPLICABLE: ["Not applicable (recorded decision)", "Non applicable (décision enregistrée)"],
  OPEN: ["Open", "Ouvert"], OVERDUE: ["Overdue", "En retard"], FULFILLED_WITH_EVIDENCE: ["Fulfilled with reviewed evidence", "Réalisé avec justificatif examiné"],
  UNSCHEDULED: ["Unscheduled", "Non planifié"], DUE: ["Scheduled", "Planifié"], OPERATIONAL: ["Operational", "Opérationnel"],
  UNREVIEWED: ["Qualified country review required", "Examen pays qualifié requis"], EXPIRED: ["Source refresh overdue", "Actualisation de la source en retard"], UNSUPPORTED: ["Country coverage unavailable", "Couverture pays indisponible"],
  PREPARED: ["Prepared", "Préparé"], REVIEWED: ["Evidence reviewed", "Justificatif examiné"], CHANGES_REQUESTED: ["Changes requested", "Modifications demandées"],
  NONE: ["No available evidence", "Aucun justificatif disponible"], CLOSE_PACK: ["Retained Close pack (not certification)", "Dossier de clôture conservé (sans certification)"],
  MANUAL_SUBMISSION: ["Manual submission evidence", "Justificatif de dépôt manuel"], MANUAL_ACKNOWLEDGEMENT: ["Manually captured acknowledgement", "Accusé saisi manuellement"],
  SANDBOX: ["Sandbox evidence", "Justificatif de test"], UNVERIFIED_AUTHORITY: ["Unverified authority evidence", "Justificatif d’autorité non vérifié"], REDACTED: ["Payroll evidence restricted", "Justificatif de paie restreint"],
}

export function ObligationRegister({ clientOrganizationId, locale = "en" }: { clientOrganizationId?: string; locale?: string }) {
  const language = locale === "fr" ? "fr" : "en", fr = language === "fr", id = useId(), epoch = useRef(0)
  const scope = useRef(clientOrganizationId); scope.current = clientOrganizationId
  const [data, setData] = useState<Register | null>(null), [busy, setBusy] = useState(false), [message, setMessage] = useState("")
  const [payroll, setPayroll] = useState(false), [selected, setSelected] = useState<ObligationItem | null>(null)
  const [code, setCode] = useState<ObligationCode>("CLOSE_EVIDENCE_COLLECTION"), [period, setPeriod] = useState("")
  const [applicability, setApplicability] = useState<ObligationCommand["applicability"]>("UNKNOWN"), [due, setDue] = useState("")
  const [evidence, setEvidence] = useState(""), [reason, setReason] = useState(""), [claim, setClaim] = useState(false)
  const [pending, setPending] = useState<ObligationCommand | null>(null), [fresh, setFresh] = useState(false), [password, setPassword] = useState("")
  const text = (en: string, french: string) => fr ? french : en
  const state = (s: string) => states[s]?.[fr ? 1 : 0] ?? s
  function resetDraft() { setSelected(null); setCode("CLOSE_EVIDENCE_COLLECTION"); setPeriod(""); setApplicability("UNKNOWN"); setDue(""); setEvidence(""); setReason(""); setClaim(false) }
  function clear() { epoch.current++; setData(null); setPending(null); setFresh(false); setPassword(""); setBusy(false); resetDraft() }
  useEffect(() => {
    clear()
    const hide = () => { if (document.visibilityState === "hidden") clear() }
    const pagehide = () => clear()
    document.addEventListener("visibilitychange", hide); window.addEventListener("pagehide", pagehide)
    return () => { epoch.current++; document.removeEventListener("visibilitychange", hide); window.removeEventListener("pagehide", pagehide) }
  // Client changes invalidate every private response and draft.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [clientOrganizationId])
  async function load(includePayroll = payroll) {
    const generation = ++epoch.current, client = clientOrganizationId
    setBusy(true); setData(null); resetDraft(); setMessage("")
    try {
      const result = await getObligationRegisterAction({ clientOrganizationId: client, includePayroll })
      if (generation !== epoch.current || scope.current !== client) return
      if (!result.success) { setPending(null); setFresh(false); setMessage(text("Access unavailable or session expired. Reload after restoring access.", "Accès indisponible ou session expirée. Rechargez après rétablissement de l’accès.")); return }
      setData(result.data); setPeriod(result.data.periods[0]?.id ?? "")
    } catch { if (generation === epoch.current) setMessage(text("Unable to load. Retry.", "Chargement impossible. Réessayez.")) }
    finally { if (generation === epoch.current) setBusy(false) }
  }
  async function execute(command: ObligationCommand) {
    const generation = ++epoch.current, client = clientOrganizationId
    setBusy(true); setPending(command); setMessage("")
    try {
      const result = await (command.command === "SAVE" ? saveObligationAction(command) : reviewObligationAction(command))
      if (generation !== epoch.current || scope.current !== client) return
      if (!result.success) {
        const error = result.code
        if (error === "FRESH_AUTH_REQUIRED") { setFresh(true); return }
        if (["FORBIDDEN", "AUTH_REQUIRED", "UNAUTHORIZED"].includes(error ?? "")) { clear(); setMessage(text("Access denied. Reload after reauthorization.", "Accès refusé. Rechargez après réautorisation.")); return }
        if (error === "CONFLICT" || error === "NOT_FOUND" || error === "BUSINESS_RULE_VIOLATION" || error === "SOD_VIOLATION") {
          setPending(null); setMessage(text("The source, evidence, version or independent review requirements changed. Reload and prepare again.", "La source, le justificatif, la version ou les conditions d’examen indépendant ont changé. Rechargez et préparez à nouveau.")); return
        }
        setMessage(text("Outcome uncertain. Reload the register or retry this exact command.", "Résultat incertain. Rechargez le registre ou réessayez la même commande.")); return
      }
      setPending(null); setFresh(false); await load(); setMessage(text("Revision recorded; current register reloaded.", "Révision enregistrée ; registre rechargé."))
    } catch { if (generation === epoch.current) setMessage(text("Outcome uncertain. Retry the retained command.", "Résultat incertain. Réessayez la commande conservée.")) }
    finally { if (generation === epoch.current) setBusy(false) }
  }
  function make(command: ObligationCommand["command"]) {
    if (!data) return
    const review = command !== "SAVE", row = selected
    if (review && !row) return
    const c = review ? row!.code : code, source = data.sources.find(s => s.code === c)!
    void execute({ clientOrganizationId, command, code: c, periodId: review ? row!.periodId : period,
      instanceId: row?.instanceId, expectedVersion: row?.version ?? 0, applicability: review ? row!.applicability : applicability,
      dueAt: review ? row!.dueAt : due ? `${due}T23:59:59.000Z` : null, claimOwnership: review ? false : claim,
      evidenceId: review ? row!.evidenceId : evidence || null, reason, expectedSourceHash: source.sourceHash, idempotencyKey: crypto.randomUUID() })
  }
  function edit(row: ObligationItem) { setSelected(row); setCode(row.code); setPeriod(row.periodId); setApplicability(row.applicability); setDue(row.dueAt?.slice(0, 10) ?? ""); setEvidence(row.evidenceId ?? ""); setReason(""); setClaim(false) }
  const disabled = busy || !!pending
  return <section data-testid="obligation-register" className="dashboard-glass-panel my-4 min-w-0 space-y-4 rounded-lg p-4" aria-labelledby={`${id}-heading`} aria-busy={busy}>
    <h3 id={`${id}-heading`} className="text-lg font-semibold">{text("Obligations and evidence register", "Registre des obligations et justificatifs")}</h3>
    <p className="text-sm text-[var(--dash-text-soft)]">{text("Operational targets are not legal deadlines. No statutory obligation is verified in this pilot. Manual or sandbox evidence is never accepted live filing. Private data clears when this tab is hidden.", "Les objectifs opérationnels ne sont pas des échéances légales. Aucune obligation légale n’est validée dans ce pilote. Un justificatif manuel ou de test n’est jamais un dépôt accepté en production. Les données privées sont effacées lorsque cet onglet est masqué.")}</p>
    <div className="flex flex-wrap items-center gap-3"><button type="button" className={button} disabled={busy} onClick={() => void load()}>{text("Load / refresh register", "Charger / actualiser le registre")}</button>
      <label className="flex min-h-11 items-center gap-2"><input type="checkbox" checked={payroll} disabled={busy} onChange={e => { clear(); setPayroll(e.target.checked) }} />{text("Include restricted payroll evidence (client payroll role required)", "Inclure les justificatifs de paie restreints (rôle paie du client requis)")}</label></div>
    <p role="status" aria-live="polite">{busy ? text("Loading…", "Chargement…") : message}</p>
    {pending && <button type="button" className={button} disabled={busy || fresh} onClick={() => void execute(pending)}>{text("Retry exact command", "Réessayer la même commande")}</button>}
    {fresh && <form className="space-y-2" onSubmit={async e => { e.preventDefault(); const generation = epoch.current; setBusy(true); try {
      const result = await stepUpWithPasswordAction({ password }); if (generation !== epoch.current) return
      setPassword(""); if (result.success) { setFresh(false); setMessage(text("Identity confirmed. Retry the retained command explicitly.", "Identité confirmée. Réessayez explicitement la commande conservée.")) }
      else setMessage(text("Password confirmation failed.", "La confirmation du mot de passe a échoué."))
    } catch { if (generation === epoch.current) setMessage(text("Confirmation unavailable. Retry.", "Confirmation indisponible. Réessayez.")) } finally { if (generation === epoch.current) setBusy(false) } }}>
      <label htmlFor={`${id}-password`}>{text("Confirm password", "Confirmer le mot de passe")}</label><input id={`${id}-password`} className={field} autoComplete="current-password" type="password" value={password} onChange={e => setPassword(e.target.value)} required />
