 const fr=locale==="fr",t=(en:string,frText:string)=>fr?frText:en
 const [data,setData]=useState<DocumentWorkspace|null>(null),[error,setError]=useState(""),[notice,setNotice]=useState(""),[busy,setBusy]=useState(false),[title,setTitle]=useState(""),[policy,setPolicy]=useState(""),[file,setFile]=useState<File|null>(null),[expiresAt,setExpiresAt]=useState(""),[replaces,setReplaces]=useState(""),[retry,setRetry]=useState<{metadata:object;file:File}|null>(null),[review,setReview]=useState<{id:string;revision:number;decision:"APPROVE"|"REJECT"}|null>(null),[reason,setReason]=useState(""),[ack,setAck]=useState(false)
 const message=useRef<HTMLParagraphElement>(null)
 const [decisionRetry,setDecisionRetry]=useState<any>(null)
 async function refresh(){const next=await execute("LIST");setData(next);if(review&&!decisionRetry){setReview(null);setAck(false)}return next}
 useEffect(()=>{let active=true;execute("LIST").then(d=>{if(active)setData(d)}).catch(()=>{if(active)setError(t("Documents could not be loaded. Your access or session may need renewal.","Impossible de charger les documents. Votre accès ou session peut nécessiter un renouvellement."))});return()=>{active=false}},[execute])
 async function run(fn:()=>Promise<void>){setBusy(true);setError("");setNotice("");try{await fn()}catch{setError(t("The outcome is unconfirmed. Refresh the status or retry the same request. Check your session and permissions if access was denied.","Le résultat est incertain. Actualisez le statut ou réessayez la même demande. Vérifiez votre session et vos droits en cas de refus."))}finally{setBusy(false);setTimeout(()=>message.current?.focus(),0)}}
 async function upload(){if(!file&&!retry)return;const envelope=retry??{metadata:{employeeId:data?.employeeId,title,policyCode:policy,idempotencyKey:crypto.randomUUID(),...(expiresAt?{expiresAt:new Date(expiresAt+'T12:00:00Z').toISOString()}:{}),...(replaces?{replacesDocumentId:replaces}:{})},file:file!};setRetry(envelope);await execute("UPLOAD",envelope);setRetry(null);setFile(null);setTitle("");setReplaces("");setNotice(t("Upload recorded. Download becomes available after scanning and independent review.","Dépôt enregistré. Le téléchargement sera disponible après analyse et vérification indépendante."));await refresh()}
 return <main className="space-y-4 min-w-0 p-4"><h1 className="text-2xl font-semibold">{t("Employment documents","Documents du personnel")}</h1><p className="text-sm text-muted-foreground">{t("Protected originals, review status and replacement history.","Originaux protégés, statut de vérification et historique des remplacements.")}</p>
 <p ref={message} tabIndex={-1} role={error?"alert":"status"} className="break-words">{error||notice}</p>
 <Button disabled={busy} variant="outline" onClick={()=>run(async()=>{await refresh();setNotice(t("Status refreshed.","Statut actualisé."))})}>{t("Refresh status","Actualiser le statut")}</Button>
