 <div><Label htmlFor="document-policy">{t("Document policy","Politique documentaire")}</Label><select id="document-policy" required className="w-full rounded-md border bg-background p-2" value={policy} onChange={e=>setPolicy(e.target.value)}><option value="">{t("Choose a policy","Choisir une politique")}</option>{data.policies.map(p=><option key={p.code} value={p.code}>{fr?p.nameFr:p.nameEn}</option>)}</select></div>
 <div><Label htmlFor="document-file">{t("PDF, PNG or JPEG — up to 5 MB","PDF, PNG ou JPEG — 5 Mo maximum")}</Label><Input id="document-file" type="file" required accept="application/pdf,image/png,image/jpeg" onChange={e=>setFile(e.target.files?.[0]??null)}/></div>
 <div><Label htmlFor="document-expiry">{t("Validity expiry (optional)","Fin de validité (facultative)")}</Label><Input id="document-expiry" type="date" value={expiresAt} onChange={e=>setExpiresAt(e.target.value)}/></div>
 <div><Label htmlFor="document-replaces">{t("Replaces (optional)","Remplace (facultatif)")}</Label><select id="document-replaces" className="w-full rounded-md border bg-background p-2" value={replaces} onChange={e=>setReplaces(e.target.value)}><option value="">{t("New document","Nouveau document")}</option>{data.documents.filter(d=>d.status==="AVAILABLE").map(d=><option key={d.id} value={d.id}>{d.title}</option>)}</select></div></fieldset>
 {retry&&<p>{t("The original request is retained for a safe retry. Its fields are locked until the outcome is confirmed.","La demande initiale est conservée pour réessayer sans doublon. Ses champs restent verrouillés jusqu’à confirmation.")}</p>}
