 <Button disabled={busy||(!retry&&(!file||!policy||title.length<2))} type="submit">{retry?t("Retry same upload","Réessayer le même dépôt"):t("Upload for review","Déposer pour vérification")}</Button></form>}
 </CardContent></Card>
 {data.historyTruncated&&<p role="status">{t("Showing the latest 200 records. Ask HR for older retained history.","Les 200 derniers documents sont affichés. Demandez l’historique conservé aux RH.")}</p>}
 {!data.documents.length&&<p>{t("No documents in your authorized scope.","Aucun document dans votre périmètre autorisé.")}</p>}
 <div className="space-y-3">{data.documents.map(d=><Card key={d.id} data-document-id={d.id}><CardHeader><CardTitle className="break-words">{d.title}</CardTitle></CardHeader><CardContent className="space-y-2 break-words"><p>{statusText[d.status]?.[fr?1:0]??d.status}</p><p className="text-sm">{fr?d.policy.nameFr:d.policy.nameEn} · {Math.ceil(d.byteLength/1024)} KB</p>
 {d.expiresAt&&<p>{t("Valid until: ","Valide jusqu’au : ")}{new Date(d.expiresAt).toLocaleDateString(locale)}</p>}
 <p>{d.employeeVisible?t("Visible to the linked employee","Visible par l’employé lié"):t("Restricted HR original","Original RH à accès restreint")}</p>
 {d.needsReplacement&&<p role="status">{t("Expired: upload a replacement and select this original.","Expiré : déposez un remplacement en sélectionnant cet original.")}</p>}
 {d.replacesDocumentId&&<p className="text-sm">{t("Linked replacement. Earlier evidence is retained.","Remplacement lié. Les preuves antérieures sont conservées.")}</p>}
 <p className="text-sm">{t("Retain until: ","Conserver jusqu’au : ")}{new Date(d.retainUntil).toLocaleDateString(locale)}{d.legalHold?t(" · Legal hold"," · Conservation obligatoire"):""}{d.evidenceBound?t(" · Bound evidence"," · Preuve liée"):""}</p>
 <div className="flex flex-wrap gap-2">{(["AVAILABLE","SUPERSEDED"].includes(d.status)||d.status==="PENDING_REVIEW"&&data.canReview)&&<Button variant="outline" disabled={busy} onClick={()=>run(async()=>{await execute("DOWNLOAD",{documentId:d.id});setNotice(t("Protected download prepared.","Téléchargement protégé préparé."))})}>{t("Download original","Télécharger l’original")}</Button>}
 {d.status==="PENDING_REVIEW"&&data.canReview&&<><Button disabled={busy||!!decisionRetry} onClick={()=>{setReview({id:d.id,revision:d.revision,decision:"APPROVE"});setAck(false);setReason("")}}>{t("Review approval","Vérifier l’approbation")}</Button><Button variant="outline" disabled={busy||!!decisionRetry} onClick={()=>{setReview({id:d.id,revision:d.revision,decision:"REJECT"});setAck(false);setReason("")}}>{t("Review rejection","Vérifier le refus")}</Button></>}</div>
 {review?.id===d.id&&<form className="space-y-2 border-t pt-3" onSubmit={e=>{e.preventDefault();void run(async()=>{const envelope=decisionRetry??{documentId:review.id,revision:review.revision,decision:review.decision,acknowledged:ack,reason};setDecisionRetry(envelope);try{await execute("REVIEW",envelope)}catch(e){if((e as {status?:number}).status===409){setDecisionRetry(null);setAck(false);setReview(null);await refresh()}throw e}setDecisionRetry(null);setReview(null);setAck(false);setNotice(t("Document decision recorded.","Décision documentaire enregistrée."));await refresh()})}}><p>{review.decision==="APPROVE"?t("Approval releases this original to its authorized audience.","L’approbation rend cet original accessible à son public autorisé."):t("Rejection keeps the original unavailable.","Le refus maintient l’original indisponible.")}</p><Label htmlFor="document-reason">{t("Decision reason","Motif de décision")}</Label><Input id="document-reason" disabled={busy||!!decisionRetry} value={reason} minLength={8} maxLength={500} required onChange={e=>setReason(e.target.value)}/><label className="flex items-start gap-2"><input type="checkbox" disabled={busy||!!decisionRetry} checked={ack} onChange={e=>setAck(e.target.checked)}/>{t("I inspected the original, policy, validity and replacement link.","J’ai vérifié l’original, la politique, la validité et le lien de remplacement.")}</label><Button disabled={busy||!ack||reason.trim().length<8} type="submit">{t("Record decision","Enregistrer la décision")}</Button></form>}
 {data.canRetain&&d.status!=="DELETED"&&<HrisDocumentRetentionControls key={d.id+':'+d.revision} document={d} locale={locale} execute={execute} refresh={refresh}/>}
 </CardContent></Card>)}</div></>}
 </main>
}

"use client"
