                <Link href={`/dashboard/inventory/items/${encodeURIComponent(item.id)}`}>{locale === "fr" ? "Consulter l’article" : "View item"}</Link>
              </DropdownMenuItem>
              <DropdownMenuItem
                onClick={() => navigator.clipboard.writeText(item.id || "")}
